                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 5 and p not in seen:
                        seen.add(p); stack.append(p)
            top = min(y for y, x in cells); bottom = max(y for y, x in cells)
            left = min(x for y, x in cells); right = max(x for y, x in cells)
            # Fill the hollow interior, including any missing top-border cell.
            for y in range(top, bottom + 1):
                for x in range(left, right + 1):
                    if grid[y][x] == 0 and left < x < right and top < y < bottom:
                        out[y][x] = 2
